#[verus::trusted]
pub open spec fn behavior_equiv<DT: Dispatch>(
    a: SimpleLogBehavior<DT>,
    b: AsynchronousSingletonBehavior<DT>,
) -> bool
    decreases a, b,
{
    ||| (a.is_Inited()
        && b.is_Inited())

